+	UIScreen *screen = _get_ui_screen(p_screen);
+	ERR_FAIL_NULL_V(screen, SCREEN_REFRESH_RATE_FALLBACK);
+	float fps = screen.maximumFramesPerSecond;
+	if ([NSProcessInfo processInfo].lowPowerModeEnabled) {
+		fps = 60;
+	}
+	return fps;
